{
  "name": "context-engine-trigger",
  "version": "0.1.5",
  "description": "Context Engine for Claude Code: compacts at each user-turn boundary so the context-engine mod can answer with the Working Context (Full Replacement per user turn; Injection within a turn). Interactive sessions only.",
  "author": {
    "name": "Jeff Kazzee"
  },
  "license": "MIT",
  "userConfig": {
    "coreCli": {
      "type": "string",
      "title": "Shared core CLI",
      "description": "Canonical absolute path to the retained checkout core/cli.ts, set by the Context Engine installer. Reinstall if the checkout moves. The checkout-relative default is for source-layout development only.",
      "default": "checkout-relative"
    }
  }
}
